24	export function UsersTable({ rows }: { rows: AdminUserRow[] }) {
25	  const columns: Column<AdminUserRow>[] = [
26	    { key: "name", header: t("admin.colName"), sortable: true },
27	    { key: "email", header: t("admin.colEmail") },
28	    {
29	      key: "role",
30	      header: t("admin.colRole"),
31	      sortable: true,
32	      render: (r) => t(ROLE_LABEL[r.role]),
